#include "../source/AudioEngine.h"
#include "../source/SessionFile.h"
#include "../source/MixExport.h"
#include "DrumOutputFixture.h"
#include <iostream>
static void require(bool ok,const char* text){if(!ok)throw std::runtime_error(text);}
int main(int argc,char** argv){juce::ScopedJuceInitialiser_GUI init;try{
 const auto folder=juce::File(juce::String::fromUTF8(argv[1]));folder.createDirectory();auto engine=std::make_unique<AudioEngine>();auto& e=*engine;e.playback.deviceRate=48000;e.playback.bpm=120;e.plugins.clock.rate=48000;
 juce::PluginDescription desc;desc.name="Drum fixture";desc.isInstrument=true;desc.pluginFormatName="Fixture";e.plugins.midiLanes[7].enabled=true;e.plugins.midiLanes[7].notes={{1,36,10,.25,.1,.8f},{2,38,10,.5,.1,.8f}};require(e.plugins.install(7,0,desc,std::make_unique<DrumFixture>(),{},false,48000).wasOk(),"install multi-output instrument");require(e.plugins.channels[7][0]->channels==7,"enable all instrument channels");
 auto& source=e.playback.tracks[7];source.midiTrack=true;source.midiSeconds=2;source.muted=true;const int kick=PluginInput::encode(7,0),snare=PluginInput::encode(7,2);e.trackInputs[0]=kick;e.trackInputChannels[0]=2;e.trackInputs[1]=snare;e.trackInputChannels[1]=1;e.monitorOverrides[0]=1;e.monitorOverrides[1]=1;e.monitorLevels[0]=1;e.monitorLevels[1]=1;e.plugins.pluginInputSources[0]=7;e.plugins.pluginInputSources[1]=7;e.playback.process=PluginRack::process;e.playback.processContext=&e.plugins;e.plugins.rebuildCompensation(e.playback);e.playback.playbackLatencyFrames=e.plugins.totalLatency;e.playback.refreshDuration();e.playback.primeMixLevels();e.playback.playing=true;
 require(e.plugins.inputAvailable(kick,2)&&e.plugins.inputAvailable(snare,1)&&e.plugins.inputWidth(snare)==1&&!e.plugins.inputAvailable(snare,2)&&!e.plugins.inputAvailable(PluginInput::encode(7,63),2),"valid/invalid output paths");
 const auto kickFile=folder.getNonexistentChildFile("Kick capture",".wav",false),snareFile=folder.getNonexistentChildFile("Snare capture",".wav",false);e.recordingRoutes={{0,kick,2,kickFile},{1,snare,1,snareFile}};require(e.recorder.startGroup(e.recordingRoutes,48000,96000).wasOk(),"start virtual record routes");e.playback.recording=true;e.playback.recordTrack=0;e.playback.recordTracks[0]=e.playback.recordTracks[1]=true;e.recordPlanActive=true;e.planTrack=0;e.planPosition=0;e.punchBegin=0;e.punchEnd=48000;e.recordingCorrection=128;
 std::array<float,997> left{},right{};float* out[]{left.data(),right.data()};double monitorPeak=0;for(int n=0;n<49000;n+=997){e.renderAudio(nullptr,0,out,2,997);for(float v:left)monitorPeak=std::max(monitorPeak,std::abs(static_cast<double>(v)));}require(monitorPeak>.01,"monitor plugin outputs on earlier audio tracks without hardware inputs");e.recorder.requestStop();require(e.recorder.waitForFinish(10000),"finish recorded WAVs");const auto takes=e.recorder.takeResults();require(takes.size()==2&&takes[0].take.frames==48000&&takes[1].take.frames==48000,"matched real-time take durations");
 juce::AudioFormatManager formats;formats.registerBasicFormats();auto k=std::unique_ptr<juce::AudioFormatReader>(formats.createReaderFor(kickFile)),s=std::unique_ptr<juce::AudioFormatReader>(formats.createReaderFor(snareFile));require(k&&s&&k->numChannels==2&&s->numChannels==1,"separate recorded stereo and mono files");juce::AudioBuffer<float> audio(2,13000);k->read(&audio,0,13000,0,true,true);require(std::abs(audio.getSample(0,6000)-.5)<1.e-5&&std::abs(audio.getSample(0,12000))<1.e-5,"recorded kick aligned and isolated");s->read(&audio,0,13000,0,true,false);require(std::abs(audio.getSample(0,12000)-.3)<1.e-5&&std::abs(audio.getSample(0,6000))<1.e-5,"recorded snare aligned and isolated");
 // Live plugin receivers also participate in offline mix export, without reusing hardware input pointers.
 e.plugins.resetGraph();const auto mixFile=folder.getNonexistentChildFile("Routed mix",".wav",false);const auto mixed=writeMixWav(e.playback,mixFile,{0,1,0,24},[]{return false;},{});require(mixed.error.isEmpty()&&mixed.frames==48000,"offline mix includes plugin-input tracks");auto mix=std::unique_ptr<juce::AudioFormatReader>(formats.createReaderFor(mixFile));audio.clear();mix->read(&audio,0,13000,0,true,true);require(std::abs(audio.getSample(0,6000))>.01&&std::abs(audio.getSample(0,12000))>.01,"routed kick and snare reach offline mix");
 // Preserve physical input capture after moving the recorder tap into the graph.
 const auto physicalFile=folder.getNonexistentChildFile("Physical capture",".wav",false);e.recordingRoutes={{0,0,1,physicalFile}};require(e.recorder.startGroup(e.recordingRoutes,48000,96000).wasOk(),"start physical capture");e.trackInputs[0]=0;e.trackInputChannels[0]=1;e.monitorOverrides[1]=-1;e.plugins.pluginInputSources[0]=-1;e.playback.recording=true;e.playback.recordTrack=0;e.playback.recordTracks.fill(false);e.playback.recordTracks[0]=true;e.recordPlanActive=true;e.planTrack=0;e.planPosition=0;e.punchBegin=0;e.punchEnd=2000;e.recordingCorrection=0;e.playback.playing=true;e.playback.seekSeconds=0;std::array<float,997> physical;physical.fill(.2f);const float* in[]{physical.data()};for(int n=0;n<3000;n+=997)e.renderAudio(in,1,out,2,997);e.recorder.requestStop();require(e.recorder.waitForFinish(10000),"finish physical WAV");const auto physicalTakes=e.recorder.takeResults();require(physicalTakes.size()==1&&physicalTakes[0].take.frames==2000,"physical capture exact length");auto physicalReader=std::unique_ptr<juce::AudioFormatReader>(formats.createReaderFor(physicalFile));audio.clear();require(physicalReader&&physicalReader->read(&audio,0,2000,0,true,false)&&std::abs(audio.getSample(0,1500)-.2)<1.e-5,"physical input preserved across graph blocks");
 SavedSession session;session.tracks.resize(8);for(int i=0;i<8;++i)session.tracks[i].name="Track "+juce::String(i+1);session.tracks[0].inputSource=kick;session.tracks[0].inputChannels=2;session.tracks[7].midiTrack=true;SavedSession reopened;const auto file=folder.getChildFile("Routing.tracksmith");require(SessionFile::decode(SessionFile::encode(session,file),file,reopened).wasOk()&&reopened.tracks[0].inputSource==kick,"plugin routing session round trip");require(PluginInput::remap(kick,7)==-1&&PluginInput::track(PluginInput::remap(kick,3))==6,"track deletion invalidation/remapping");
 std::cout<<"PASS: enabled multi-output host, instrument-first graph order, live mono/stereo monitoring, real-time separate WAV recording without physical inputs, 128-sample alignment, 997-frame callback boundaries, session routing round trip and deletion remapping.\n";
 }catch(const std::exception& ex){std::cerr<<"FAIL: "<<ex.what()<<'\n';return 1;}return 0;}
